+```cpp
+Account* BankService::createSavingsAccount(const std::string& username,
+                                            const std::string& accountId,
+                                            double rate) {
+    User* user = findUser(username);
+    if (user == nullptr || accountId.empty() ||
+        findAccountState(username, accountId) != nullptr) {
+        return nullptr;
+    }
+
+    // 创建派生类对象，并以基类指针形式存入用户账户列表。
+    auto account = std::make_unique<SavingsAccount>(currentDate_, accountId, rate);
+    Account* raw = user->addAccount(std::move(account));
+
+    // 账户状态表使用 username + accountId 作为键，快速定位账户。
+    AccountState state;
+    state.account = raw;
+    state.type = AccountType::Savings;
+    state.rate = rate;
+    state.accDate = currentDate_;
+    accountStates_[makeKey(username, accountId)] = state;
+    return raw;
+}
