+存取款核心算法如下：
+
+```cpp
+bool BankService::withdraw(const std::string& username,
+                           const std::string& accountId, double amount,
+                           const std::string& desc) {
+    if (amount <= 0) {
+        return false;
+    }
+    AccountState* state = findAccountState(username, accountId);
+    if (state == nullptr) {
+        return false;
+    }
+
+    // 储蓄账户不能透支；信用账户不能超过授信额度。
+    if (state->type == AccountType::Savings && amount > state->balance) {
+        return false;
+    }
+    if (state->type == AccountType::Credit && amount - state->balance > state->credit) {
+        return false;
+    }
+
+    // 更新账户、余额、计息累计值和交易流水。
+    state->account->withdraw(currentDate_, amount, desc);
+    state->balance = round2(state->balance - amount);
+    accumulatorChange(*state, currentDate_, accumulatorValue(*state));
+    appendTransaction(username, accountId, -amount, state->balance, desc);
+    return true;
+}
+```
