+    auto req_res = read_http_request(conn, config.http_config);
+    if (!req_res) {
+        return render_error(conn, HttpStatus::BadRequest, "bad request");
+    }
+
+    try {
+        // BankService 内保存 users、accounts、transactions，必须串行修改。
+        std::lock_guard<std::mutex> lock(service_mutex);
+        const HttpRequest& request = req_res.value();
+
+        if (request.method == HttpMethod::GET) {
+            return handle_get(conn, request.path, request.query, service);
+        }
+        if (request.method == HttpMethod::POST) {
+            return handle_post(conn, request.path, request.body, service);
+        }
+        return render_error(conn, HttpStatus::MethodNotAllowed,
+                            "method not allowed");
+    } catch (const std::exception& ex) {
+        return render_error(conn, HttpStatus::InternalServerError, ex.what());
+    }
+}
+```
+
+### 功能三：增加了 C++ 的 Exception 处理错误
+
+#### 1. 设计
+
+异常处理分为三层：
+
+1. 模型层定义领域异常，如 `AccountException`、`InsufficientFundsException`、`InsufficientCreditException` 和 `DateException`。
+2. 持久化层在文件无法打开、文件格式非法时抛出 `std::runtime_error`。
+3. Web 请求入口统一捕获 `std::exception`，转换成错误页面或启动日志。
+
+这种设计使底层函数只负责报告错误，上层统一决定如何展示错误，避免错误处理逻辑散落在各处。
+
+异常类关系如下：
+
+```mermaid
+classDiagram
+    class runtime_error
+    class invalid_argument
+    class AccountException
+    class InsufficientFundsException
+    class InsufficientCreditException
+    class DateException
+    runtime_error <|-- AccountException
+    AccountException <|-- InsufficientFundsException
+    AccountException <|-- InsufficientCreditException
+    invalid_argument <|-- DateException
+```
+
+#### 2. 实现
+
+账户异常用于表达业务层错误：
+
+```cpp
+class AccountException : public std::runtime_error {
+   public:
+    explicit AccountException(const std::string& message)
+        : std::runtime_error(message) {}
+};
+
+class InsufficientFundsException : public AccountException {
+   public:
+    // 储蓄账户余额不足时使用该异常。
+    InsufficientFundsException() : AccountException("not enough money") {}
+};
+
+class InsufficientCreditException : public AccountException {
+   public:
+    // 信用账户超过授信额度时使用该异常。
+    InsufficientCreditException() : AccountException("not enough credit") {}
+};
+```
+
+持久化读取账户时对文件状态和字段合法性进行检查，发现问题立即抛出异常：
+
+```cpp
+void BankService::loadAccounts(const std::string& filename) {
+    std::ifstream in(filename);
+    if (!in) {
+        // 文件打不开属于不可恢复的持久化错误，交给上层处理。
+        throw std::runtime_error("cannot open account file for reading");
+    }
+
+    while (in >> username >> accountId >> typeCode >> balance >> credit >> rate >>
+           fee >> accYear >> accMonth >> accDay >> accValue >> accSum) {
+        User* user = findUser(username);
+        if (user == nullptr || accountId.empty() ||
+            findAccountState(username, accountId) != nullptr) {
+            // 用户不存在、账号为空或账号重复都说明文件内容不合法。
+            throw std::runtime_error("invalid account file");
+        }
+
+        AccountType type = accountTypeFromCode(typeCode);
+        if (type == AccountType::Savings && (balance < 0 || credit != 0 || fee != 0)) {
+            throw std::runtime_error("invalid account file");
+        }
+    }
+}
+```
+
+Web 层捕获异常并转换为 HTTP 500 错误页面：
+
+```cpp
+try {
+    std::lock_guard<std::mutex> lock(service_mutex);
+    if (request.method == HttpMethod::GET) {
+        return handle_get(conn, request.path, request.query, service);
+    }
+    if (request.method == HttpMethod::POST) {
+        return handle_post(conn, request.path, request.body, service);
+    }
+    return render_error(conn, HttpStatus::MethodNotAllowed, "method not allowed");
+} catch (const std::exception& ex) {
+    // 捕获所有标准异常，避免单个请求导致服务器进程退出。
+    return render_error(conn, HttpStatus::InternalServerError, ex.what());
+}
+```
+
+程序启动时读取历史数据，如果文件不存在或格式错误，则记录错误并继续启动服务器：
+
+```cpp
+try {
+    load_existing_data(service);
+} catch (const std::exception& ex) {
+    // 启动阶段的数据加载错误不终止 Web 服务，只在控制台提示。
+    std::cerr << "data load skipped: " << ex.what() << '\n';
+}
+```
+
+### 功能四：增加了用户，用户可以创建多个账户
+
+#### 1. 设计
+
+用户模块以 `User` 为中心，每个用户保存用户名、密码和账户列表。账户采用基类 `Account` 加派生类 `SavingsAccount`、`CreditAccount` 的继承结构，使用 `std::unique_ptr<Account>` 实现多态存储。`BankService` 作为业务外观类，统一负责注册登录、开户、存取款、交易查询和月度统计。
+
+核心类图如下：
+
+```mermaid
+classDiagram
+    class User {
+        +string username
+        +string password
+        +vector~unique_ptr~Account~~ accounts
+        +addAccount(unique_ptr~Account~) Account*
+    }
+    class Account {
+        -string id
+        -double balance
+        +deposit(date, amount, desc)*
+        +withdraw(date, amount, desc)*
+        +settle(date)*
+        +getId() string
+    }
+    class SavingsAccount {
+        -Accumulator acc
+        -double rate
+    }
+    class CreditAccount {
+        -Accumulator acc
+        -double credit
+        -double rate
+        -double fee
+    }
+    class BankService {
+        -vector~User~ users_
+        -vector~Transaction~ transactions_
+        -unordered_map~string, AccountState~ accountStates_
+    }
+    User "1" o-- "many" Account
+    Account <|-- SavingsAccount
+    Account <|-- CreditAccount
+    BankService --> User
+```
+
+用户与多账户算法设计：
+
+1. 注册时检查用户名非空且不能重复，然后加入 `users_`。
+2. 登录时根据用户名查找用户，再比较密码。
+3. 开户时先找到所属用户，再检查账户号是否为空或重复。
+4. 根据账户类型创建 `SavingsAccount` 或 `CreditAccount`，用 `unique_ptr` 放入用户的 `accounts`。
+5. `BankService` 同时在 `accountStates_` 中保存账户余额、利率、额度、年费和计息累计值，便于业务计算和持久化。
+
+#### 2. 实现
+
+`User` 通过 `vector<unique_ptr<Account>>` 保存多个账户：
+
+```cpp
+struct User {
+    std::string username;
+    std::string password;
+    std::vector<std::unique_ptr<Account>> accounts;
+
+    Account* addAccount(std::unique_ptr<Account> account) {
+        // 先保存裸指针，便于 BankService 建立账户状态索引。
+        Account* raw = account.get();
+        // unique_ptr 转移所有权，保证账户生命周期跟随用户对象。
+        accounts.push_back(std::move(account));
+        return raw;
+    }
+};
+```
+
+注册和登录的实现如下：
+
+```cpp
+bool BankService::registerUser(const std::string& username,
+                               const std::string& password) {
+    // 用户名不能为空，也不能与已有用户重复。
+    if (username.empty() || findUser(username) != nullptr) {
+        return false;
+    }
+    users_.emplace_back(username, password);
+    return true;
+}
+
+bool BankService::login(const std::string& username,
+                        const std::string& password) const {
+    const User* user = findUser(username);
+    // 找到用户且密码一致才允许进入系统。
+    return user != nullptr && user->password == password;
+}
+```
+
+创建储蓄账户时，将账户对象和账户状态同时建立：
+
+```cpp
+Account* BankService::createSavingsAccount(const std::string& username,
+                                            const std::string& accountId,
+                                            double rate) {
+    User* user = findUser(username);
+    if (user == nullptr || accountId.empty() ||
+        findAccountState(username, accountId) != nullptr) {
+        return nullptr;
+    }
+
+    // 创建派生类对象，并以基类指针形式存入用户账户列表。
+    auto account = std::make_unique<SavingsAccount>(currentDate_, accountId, rate);
+    Account* raw = user->addAccount(std::move(account));
+
+    // 账户状态表使用 username + accountId 作为键，快速定位账户。
+    AccountState state;
+    state.account = raw;
+    state.type = AccountType::Savings;
+    state.rate = rate;
+    state.accDate = currentDate_;
+    accountStates_[makeKey(username, accountId)] = state;
+    return raw;
+}
+```
+
+存取款核心算法如下：
+
+```cpp
+bool BankService::withdraw(const std::string& username,
+                           const std::string& accountId, double amount,
+                           const std::string& desc) {
+    if (amount <= 0) {
+        return false;
+    }
+    AccountState* state = findAccountState(username, accountId);
+    if (state == nullptr) {
+        return false;
+    }
+
+    // 储蓄账户不能透支；信用账户不能超过授信额度。
+    if (state->type == AccountType::Savings && amount > state->balance) {
+        return false;
+    }
+    if (state->type == AccountType::Credit && amount - state->balance > state->credit) {
+        return false;
+    }
+
+    // 更新账户、余额、计息累计值和交易流水。
+    state->account->withdraw(currentDate_, amount, desc);
+    state->balance = round2(state->balance - amount);
+    accumulatorChange(*state, currentDate_, accumulatorValue(*state));
+    appendTransaction(username, accountId, -amount, state->balance, desc);
+    return true;
+}
+```
+
+### 功能五：增加了用户以及记录的持久化
+
+#### 1. 设计
+
+系统将运行期数据拆分为三类文件保存：用户文件保存用户名和密码，交易文件保存每笔交易流水，账户文件保存账户类型、余额、利率、额度、年费和计息状态。启动时如果文件存在则依次加载，业务操作后调用 `save_data` 统一写回。
+
+持久化对象关系如下：
+
+```mermaid
+flowchart LR
+    BankService[BankService]
+    Users[(users.txt)]
+    Transactions[(transactions.txt)]
+    Accounts[(accounts.txt)]
+    BankService -->|saveUsers/loadUsers| Users
+    BankService -->|saveTransactions/loadTransactions| Transactions
+    BankService -->|saveAccounts/loadAccounts| Accounts
+```
+
+持久化算法设计：
+
+1. 启动时判断用户、交易、账户文件是否存在。
+2. 先加载用户，再加载交易；只有用户和账户文件都存在时才恢复账户，因为账户必须依附于用户。
+3. 每次注册、开户、存款、取款成功后，统一保存用户、交易和账户三类数据。
+4. 加载账户时重建 `Account` 派生对象和 `AccountState`，并通过 `restoreAccountBalance` 恢复账户余额显示状态。
+
+#### 2. 实现
+
+启动阶段的数据加载流程如下：
+
+```cpp
+void load_existing_data(BankService& service) {
+    namespace fs = std::filesystem;
+    bool hasUsers = fs::exists(users_file);
+    bool hasTransactions = fs::exists(transactions_file);
+    bool hasAccounts = fs::exists(accounts_file);
+
+    // 用户是账户的所有者，因此必须先加载用户。
+    if (hasUsers) {
+        service.loadUsers(std::string(users_file));
+    }
+    if (hasTransactions) {
+        service.loadTransactions(std::string(transactions_file));
+    }
+    // 账户依赖用户对象，只有用户和账户文件同时存在时才恢复账户。
+    if (hasUsers && hasAccounts) {
+        service.loadAccounts(std::string(accounts_file));
+    }
+}
+```
+
+业务数据统一保存到三个文件：
+
+```cpp
+void save_data(const BankService& service) {
+    // 将内存中的用户、交易流水、账户状态一次性写回文件。
+    service.save(std::string(users_file), std::string(transactions_file),
+                 std::string(accounts_file));
+}
+
+void BankService::save(const std::string& userFilename,
+                       const std::string& transactionFilename,
+                       const std::string& accountFilename) const {
+    saveUsers(userFilename);
+    saveTransactions(transactionFilename);
+    saveAccounts(accountFilename);
+}
+```
+
+交易记录保存和读取的核心代码如下：
+
+```cpp
+static void saveToFile(const std::vector<Transaction>& transactions,
+                       const std::string& filename) {
+    std::ofstream out(filename);
+    if (!out) {
+        throw std::runtime_error("cannot open transaction file for writing");
+    }
+
+    for (const Transaction& transaction : transactions) {
+        // 使用制表符分隔字段，最后保存描述文本。
+        out << transaction.date.getYear() << '\t'
+            << transaction.date.getMonth() << '\t'
+            << transaction.date.getDay() << '\t' << transaction.username
+            << '\t' << transaction.accountId << '\t' << transaction.amount
+            << '\t' << transaction.balance << '\t' << transaction.desc << '\n';
+    }
+}
+
+static std::vector<Transaction> loadFromFile(const std::string& filename) {
+    std::ifstream in(filename);
+    if (!in) {
+        throw std::runtime_error("cannot open transaction file for reading");
+    }
+
+    std::vector<Transaction> transactions;
+    while (in >> year >> month >> day >> username >> accountId >> amount >> balance) {
+        // 前面的字段用 >> 读取，描述可能包含空格，因此用 getline 读取行尾。
+        in.get();
+        std::getline(in, desc);
+        transactions.emplace_back(Date(year, month, day), username, accountId,
+                                  amount, balance, desc);
+    }
+    return transactions;
+}
+```
+
+账户状态保存时不仅保存余额，还保存计息累计信息，保证重启后仍能继续计算利息：
+
+```cpp
+void BankService::saveAccounts(const std::string& filename) const {
+    std::ofstream out(filename);
+    if (!out) {
+        throw std::runtime_error("cannot open account file for writing");
+    }
+
+    for (const User& user : users_) {
+        for (const std::unique_ptr<Account>& account : user.accounts) {
+            const AccountState* state = findAccountState(user.username,
+                                                         account->getId());
+            if (state == nullptr) {
+                continue;
+            }
+
+            // 依次写入用户、账号、类型、余额、额度、利率、年费和计息状态。
+            out << user.username << '\t' << account->getId() << '\t'
+                << accountTypeCode(state->type) << '\t' << state->balance << '\t'
+                << state->credit << '\t' << state->rate << '\t' << state->fee
+                << '\t' << state->accDate.getYear() << '\t'
+                << state->accDate.getMonth() << '\t' << state->accDate.getDay()
+                << '\t' << state->accValue << '\t' << state->accSum << '\n';
+        }
+    }
+}
+```
+
+通过以上五个功能的设计与实现，系统从原本的命令行账户管理程序扩展为支持 Web 访问、多用户、多账户、并发请求、异常处理和数据持久化的个人银行账户管理系统。
-
-### 2. 实现
*** End Patch

