158: 表单处理以注册为例，先校验输入，再调用业务层，最后保存数据并返回主页：
159: 
160: ```cpp
161: Result<void> handle_register(Connection& conn, BankService& service,
162:                              const QueryFields& form) {
163:     // 从 POST 请求体中取出表单字段。
164:     std::string username = field(form, "username");
165:     std::string password = field(form, "password");
166:     std::string confirm = field(form, "confirm_password");
167: 
168:     // 输入为空或两次密码不一致时，返回 400 错误页面。
169:     if (username.empty() || password.empty()) {
170:         return render_error(conn, HttpStatus::BadRequest,
171:                             "username and password are required");
172:     }
173:     if (!confirm.empty() && confirm != password) {
174:         return render_error(conn, HttpStatus::BadRequest,
175:                             "password confirmation does not match");
176:     }
177: 
178:     // 调用 BankService 创建用户，失败说明用户已存在或用户名无效。
179:     if (!service.registerUser(username, password)) {
180:         return render_error(conn, HttpStatus::BadRequest,
181:                             "user already exists or username is invalid");
182:     }
183: 
184:     // 每次修改业务数据后立即持久化，保证刷新或重启后数据不丢失。
185:     save_data(service);
186:     return render_home(conn, service, username);
187: }
