371: 持久化读取账户时对文件状态和字段合法性进行检查，发现问题立即抛出异常：
372: 
373: ```cpp
374: void BankService::loadAccounts(const std::string& filename) {
375:     std::ifstream in(filename);
376:     if (!in) {
377:         // 文件打不开属于不可恢复的持久化错误，交给上层处理。
378:         throw std::runtime_error("cannot open account file for reading");
379:     }
380: 
381:     while (in >> username >> accountId >> typeCode >> balance >> credit >> rate >>
382:            fee >> accYear >> accMonth >> accDay >> accValue >> accSum) {
383:         User* user = findUser(username);
