521: 创建储蓄账户时，将账户对象和账户状态同时建立：
522: 
523: ```cpp
524: Account* BankService::createSavingsAccount(const std::string& username,
525:                                             const std::string& accountId,
526:                                             double rate) {
527:     User* user = findUser(username);
528:     if (user == nullptr || accountId.empty() ||
529:         findAccountState(username, accountId) != nullptr) {
530:         return nullptr;
531:     }
532: 
533:     // 创建派生类对象，并以基类指针形式存入用户账户列表。
534:     auto account = std::make_unique<SavingsAccount>(currentDate_, accountId, rate);
535:     Account* raw = user->addAccount(std::move(account));
536: 
537:     // 账户状态表使用 username + accountId 作为键，快速定位账户。
538:     AccountState state;
539:     state.account = raw;
540:     state.type = AccountType::Savings;
541:     state.rate = rate;
542:     state.accDate = currentDate_;
543:     accountStates_[makeKey(username, accountId)] = state;
544:     return raw;
545: }
546: ```
547: 
548: 存取款核心算法如下：
549: 
550: ```cpp
551: bool BankService::withdraw(const std::string& username,
552:                            const std::string& accountId, double amount,
553:                            const std::string& desc) {
554:     if (amount <= 0) {
555:         return false;
556:     }
557:     AccountState* state = findAccountState(username, accountId);
558:     if (state == nullptr) {
559:         return false;
560:     }
561: 
562:     // 储蓄账户不能透支；信用账户不能超过授信额度。
563:     if (state->type == AccountType::Savings && amount > state->balance) {
564:         return false;
565:     }
566:     if (state->type == AccountType::Credit && amount - state->balance > state->credit) {
567:         return false;
568:     }
569: 
570:     // 更新账户、余额、计息累计值和交易流水。
571:     state->account->withdraw(currentDate_, amount, desc);
572:     state->balance = round2(state->balance - amount);
573:     accumulatorChange(*state, currentDate_, accumulatorValue(*state));
574:     appendTransaction(username, accountId, -amount, state->balance, desc);
575:     return true;
576: }
577: ```
